import os
import sys
import unittest
import tempfile
from unittest.mock import patch

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _loader import load, read_file


class BurnReportParsingTests(unittest.TestCase):
    """Exercises the combiner against real reports generated by the other
    four tools' own report writers — not hand-crafted fixture text — so a
    format change in any of them will break this test too."""

    def setUp(self):
        self.tmpdir = tempfile.TemporaryDirectory()

        self.burnscanner = load("burnscanner")
        self.burnscanner.REPORT_DIR = self.tmpdir.name
        self.burnrecon = load("burnrecon")
        self.burnrecon.REPORT_DIR = self.tmpdir.name
        self.burnweb = load("burnweb")
        self.burnweb.REPORT_DIR = self.tmpdir.name
        self.burncracker = load("burncracker")
        self.burncracker.REPORT_DIR = self.tmpdir.name
        self.burnreport = load("burnreport")
        self.burnreport.REPORT_DIR = self.tmpdir.name

        scan_results = [{
            'ip': '192.168.1.10', 'hostname': 'router.lan', 'mac': 'AA:BB:CC:DD:EE:FF', 'vendor': 'Acme',
            'services': [{'port': '22', 'protocol': 'tcp', 'name': 'ssh',
                          'product': 'OpenSSH', 'version': '8.2'}],
            'cves': {'22': [{'id': 'CVE-2020-1234', 'description': 'd',
                              'score': 7.5, 'severity': 'HIGH'}]},
            'vulns': [], 'exploits': [],
        }]
        findings = self.burnscanner.analyze_findings(scan_results)
        self.scanner_report = self.burnscanner.generate_report(scan_results, "example.com", findings)

        recon_findings = [{"title": "Missing X-Frame-Options", "detail": "clickjacking risk",
                            "severity": "MEDIUM", "remediation": "Add header"}]
        self.burnrecon.note("RECON-501", "No Shodan API key configured.")
        self.recon_report = self.burnrecon.generate_report("example.com", {}, recon_findings)

        web_findings = [{"title": "Server Version Disclosed", "detail": "nginx/1.18",
                          "severity": "LOW", "remediation": "Suppress version"}]
        self.burnweb.note("WEB-401", "No exposed sensitive files found.")
        self.web_report = self.burnweb.generate_report("example.com", {}, web_findings, None)

        self.burncracker.note("CRACK-401", "Password not found in wordlist.")
        self.crack_report = self.burncracker.save_results(
            {"essid": "HomeWifi", "bssid": "11:22:33:44:55:66", "channel": "6", "enc": "WPA2"}, None
        )

    def tearDown(self):
        self.tmpdir.cleanup()

    def test_list_reports_finds_all_generated_reports(self):
        reports = self.burnreport.list_reports()
        names = {os.path.basename(r) for r in reports}
        self.assertIn(os.path.basename(self.scanner_report), names)
        self.assertIn(os.path.basename(self.recon_report), names)
        self.assertIn(os.path.basename(self.web_report), names)
        self.assertIn(os.path.basename(self.crack_report), names)

    def test_identify_tool_names_each_report_correctly(self):
        self.assertEqual(self.burnreport.identify_tool(self.scanner_report), "Burn Scanner")
        self.assertEqual(self.burnreport.identify_tool(self.recon_report), "Burn Recon")
        self.assertEqual(self.burnreport.identify_tool(self.web_report), "Burn Web")
        self.assertEqual(self.burnreport.identify_tool(self.crack_report), "Burn Crack")

    def test_parse_target_handles_both_target_and_target_ssid_labels(self):
        scanner_lines = read_file(self.scanner_report).splitlines()
        crack_lines = read_file(self.crack_report).splitlines()
        self.assertEqual(self.burnreport.parse_target(scanner_lines), "example.com")
        self.assertEqual(self.burnreport.parse_target(crack_lines), "HomeWifi")

    def test_parse_findings_section_matches_scanner_and_recon_and_web(self):
        scanner_lines = read_file(self.scanner_report).splitlines()
        recon_lines = read_file(self.recon_report).splitlines()
        web_lines = read_file(self.web_report).splitlines()

        sf = self.burnreport.parse_findings_section(scanner_lines)
        rf = self.burnreport.parse_findings_section(recon_lines)
        wf = self.burnreport.parse_findings_section(web_lines)

        self.assertEqual(len(sf), 1)
        self.assertEqual(sf[0]["severity"], "HIGH")
        self.assertIn("CVE-2020-1234", sf[0]["title"])

        self.assertEqual(len(rf), 1)
        self.assertEqual(rf[0]["severity"], "MEDIUM")

        self.assertEqual(len(wf), 1)
        self.assertEqual(wf[0]["severity"], "LOW")

    def test_parse_diagnostics_section_handles_dash_and_equals_underlines(self):
        recon_lines = read_file(self.recon_report).splitlines()
        crack_lines = read_file(self.crack_report).splitlines()
        rd = self.burnreport.parse_diagnostics_section(recon_lines)
        cd = self.burnreport.parse_diagnostics_section(crack_lines)
        self.assertTrue(any("RECON-501" in d for d in rd))
        self.assertTrue(any("CRACK-401" in d for d in cd))

    def test_end_to_end_combine_merges_all_four_sources(self):
        with patch("builtins.input", return_value="all"):
            self.burnreport.main()
        combined = [f for f in self.burnreport.list_reports()
                    if os.path.basename(f).startswith("burnreport_")]
        self.assertTrue(combined, "no combined report was written")
        content = read_file(combined[0])
        self.assertIn("CVE-2020-1234", content)
        self.assertIn("X-Frame-Options", content)
        self.assertIn("Server Version Disclosed", content)
        self.assertIn("RECON-501", content)
        self.assertIn("CRACK-401", content)
        self.assertIn("1 HIGH", content)
        self.assertIn("1 MEDIUM", content)
        self.assertIn("1 LOW", content)


class BurnReportEmptyStateTests(unittest.TestCase):
    def setUp(self):
        self.tmpdir = tempfile.TemporaryDirectory()
        self.mod = load("burnreport")
        self.mod.REPORT_DIR = self.tmpdir.name

    def tearDown(self):
        self.tmpdir.cleanup()

    def test_no_reports_exits_cleanly(self):
        with self.assertRaises(SystemExit) as ctx:
            self.mod.main()
        self.assertEqual(ctx.exception.code, 3)


if __name__ == "__main__":
    unittest.main()
